SELECT jsonb_build_array(d.id::text,d.task_id::text,d.revision::text,d.config_json,d.validation_config_digest,d.validation_environment_digest,to_char(d.validated_at,'YYYY-MM-DD"T"HH24:MI:SS.US'),to_char(d.validation_expires_at,'YYYY-MM-DD"T"HH24:MI:SS.US'),to_char(d.gmt_create,'YYYY-MM-DD"T"HH24:MI:SS.US'),to_char(d.gmt_modified,'YYYY-MM-DD"T"HH24:MI:SS.US'))::text AS canonical_value FROM public.fs_sync_task_draft d JOIN public.fs_sync_task t ON t.id=d.task_id WHERE t.task_code='PILOT_PREVIEW' ORDER BY d.id LIMIT 1001
